  for(auto site:sites){Json args={{"address",site.a},{"enabled",true},{"log",false}};if(*site.condition)args["condition"]=site.condition;req("cpu.breakpoint.add",args);owned.push_back(site.a);}
  notify(L"Capture active. In PPSSPP, move from Divas toward DLC, try Cross, then return. Use your controller normally.");req("cpu.resume");auto end=std::chrono::steady_clock::now()+std::chrono::seconds(seconds);size_t hits=0;bool returnArmed=true;std::map<uint32_t,int> siteHits;
