   Json ev={{"cpu",st},{"pc",hex(pc)}};for(auto site:sites)if(site.a==pc)ev["site"]=site.label;for(const char* r:{"a0","a1","a2","a3","t0","s2","s3","s5","s7","fp","at","v0","v1","ra","sp"})ev["registers"][r]=reg(r);ev["disassembly"]=dis(pc,3);
   if(pc==0x08f58110){owner=reg("a0");req("cpu.breakpoint.remove",{{"address",pc}});owned.erase(found);}else if(pc==0x08f583b8||pc==0x08f58338||pc==0x08f58504||pc==0x08f586ac)owner=reg("s7");else if(pc==0x08f586d8)owner=reg("a0");else if(pc==0x08f58ab0){auto candidate=reg("a0");if(pointer(candidate,0xb488)){auto main=word(candidate+16);if(pointer(main,0xb060)&&pointer(word(main+0xb058),0x60)){owner=candidate;ev["owner_source"]="Availability caller a0, validated main/grid pointers; confirm against cursor entry when hit.";}}}
